/* Extracted established native layout policy; generated by extract_layout_engine.py. */
static int want_four(void) { return layout_cfg.enabled && layout_cfg.layout == LAYOUT_4DECK; }
static int want_two(void) { return layout_cfg.enabled && layout_cfg.layout == LAYOUT_2DECK; }
/* The native Beat FX box belongs to the waveform screen, independently of
 * four-deck geometry. Only an authorized settings USB may enable it. */
static int want_sidebar(void) { return layout_cfg.authorized && layout_cfg.sidebar; }

/* 2 DECK: the overview field shows EP136's own 2-deck overview instead of the 4-deck one.
 * EP136's choice is kept and put back when the tab changes. */
static char *g_prev_owner;          /* overview field we changed, or NULL; message thread */
static int g_prev_vis2, g_prev_vis4; /* EP136's visibility of the two overviews then */
static void overviews_converge(char *prev, int two) {
    char *o2 = child_of_class(prev, "N3gui8waveform30EntireWaveform2DeckFieldWidgetE", 0);
    char *o4 = child_of_class(prev, "N3gui8waveform30EntireWaveform4DeckFieldWidgetE", 0);
    if (two && o2 && o4) {
        if (g_prev_owner != prev) {
            g_prev_owner = prev;
            g_prev_vis2 = comp_visible_now(o2);
            g_prev_vis4 = comp_visible_now(o4);
            olog("layout: overviews 2-deck\n");
        }
        comp_visible(o4, 0);
        comp_visible(o2, 1);
    } else if (g_prev_owner == prev && o2 && o4) {
        comp_visible(o2, g_prev_vis2);
        comp_visible(o4, g_prev_vis4);
        g_prev_owner = NULL;
        olog("layout: overviews back\n");
    }
}

static int g_lanes_four; /* lanes currently in the 4-deck layout; message thread */
static int g_lanes_narrow; /* stock-pair lanes clipped for the sidebar */
static void *g_view;     /* the WaveformView, checked by vtable at use; message thread */
static void stock_lanes_clip(const struct wfv_parts *p, int sidebar) {
    for (int i = 0; i < 4; i++) {
        const int *b = (const int *)(p->lane[i] + COMP_BOUNDS);
        comp_bounds(p->lane[i], b[0], b[1],
                    sidebar ? FX_SIDEBAR_LANE_WIDTH : 1124, b[3]);
    }
}
/* update() runs for every visible frame. It may restore stock lane visibility.
 * Repair the validated components directly on ordinary frames and periodically
 * repeat the complete RTTI/child walk to discover any structural changes. */
static void *g_fast_view, *g_fast_lane_obj[4];
static int g_fxbox_applied=-1;
static struct wfv_parts g_fast_parts;
static char *g_fast_mixer;
static int g_fast_pitch, g_fast_sidebar, g_fast_ticks;
static int layout_fast_repair(void *view) {
    if(view!=g_fast_view || !g_lanes_four || !want_four() ||
       *(uintptr_t *)view!=WFV_VT || ++g_fast_ticks>=16)
        return 0;
    int pitch=lane4_pitch();
    if(pitch!=g_fast_pitch || !g_fast_mixer ||
       g_mixer_hidden!=g_fast_mixer ||
       *(char **)((char *)view+WFV_PREVIEWS)!=g_fast_parts.prev ||
       *(char **)((char *)view+WFV_DECKINFO)!=g_fast_parts.dif ||
       *(char **)(g_fast_parts.dif+COMP_PARENT)!=(char *)view)
        return 0;
    int sidebar=g_fast_sidebar;
    if(sidebar && (!g_fx_sidebar.root || g_fx_sidebar.owner!=(char *)view ||
                   *(char **)(g_fx_sidebar.root+COMP_PARENT)!=(char *)view ||
                   comp_visible_now(g_fx_sidebar.time)==comp_visible_now(g_fx_sidebar.percent)))
        return 0;
    for(int i=0;i<8;i++)
        if(g_mixer_parts[i] && comp_visible_now(g_mixer_parts[i]))return 0;
    for(int i=0;i<4;i++) {
        if(*(void **)((char *)view+lane_field[i])!=g_fast_lane_obj[i] ||
           *(void **)(g_fast_parts.dif+DIF_CARD0+8*i)!=g_fast_parts.card_obj[i])
            return 0;
    }
    comp_size(g_fast_parts.dif,156,1+4*pitch);
    for(int i=0;i<4;i++) {
        comp_bounds(g_fast_parts.lane[i],156,LANE4_Y0+pitch*lane_four_row(i),
                    sidebar?FX_SIDEBAR_LANE_WIDTH:1124,pitch);
        comp_visible(g_fast_parts.lane[i],1);
        comp_bounds(g_fast_parts.card[i],5,1+pitch*lane_four_row(i),140,pitch);
    }
    comp_bounds(g_fast_parts.prev,0,PREV4_Y,1280,204);
    comp_visible(g_fast_parts.prev,layout_cfg.overviews);
    if(sidebar)fx_sidebar_show();
    return 1;
}
static int layout_converge(void *view) {
    if(g_fxbox_applied!=(int)layout_cfg.sidebar) {g_fxbox_applied=layout_cfg.sidebar;g_fast_view=NULL;}
    if(layout_fast_repair(view))return 1;
    g_fast_view=NULL;
    struct wfv_parts p;
    if (!wfv_parts(view, &p))
        return 0;
    g_view = view;
    int four = want_four();
    int pitch = lane4_pitch();
    overviews_converge(p.prev, want_two());
    char *vc = *(char **) (p.lane[0] + COMP_PARENT);
    char *mixer = is_class(vc, "N3gui8waveform12WaveformViewE") ? view_mixer(vc) : NULL;
    if (four && mixer) {
        int first = g_mixer_hidden != mixer;
        if (first) {
            mixer_restore();
            olog("layout: mixer FX row with native Beat FX sidebar\n");
        }
        g_mixer_hidden = mixer;
        mixer_converge(mixer, first);
    } else if (g_mixer_hidden) {
        mixer_restore();
    }
    if(want_sidebar() || !four || !mixer)fx_overlay_restore();
    int sidebar=want_sidebar() && mixer && fx_sidebar_converge((char *)view,mixer);
    if(!want_sidebar() || !mixer)fx_sidebar_restore();
    if(four && mixer && !want_sidebar())fx_overlay_converge((char *)view,mixer);
    if (four) {
        for (int i = 0; i < 4; i++) {
            /* Narrow the viewport, not time/beat coordinates. The fixed-width
             * native content is clipped by this outer field at its right edge;
             * markers, cues and playhead retain their common native zoom. */
            comp_bounds(p.lane[i], 156, LANE4_Y0 + pitch * lane_four_row(i),
                        sidebar ? FX_SIDEBAR_LANE_WIDTH : 1124, pitch);
            lane_inner(p.lane[i], pitch);
            comp_visible(p.lane[i], 1);
        }
        comp_bounds(p.prev, 0, PREV4_Y, 1280, 204);
        comp_visible(p.prev, layout_cfg.overviews);
        if (!g_lanes_four)
            olog("layout: lanes 4-deck\n");
        g_lanes_four = 1;
    } else if (g_lanes_four) {
        /* Stock pairs: 1 and 2 shown; update() swaps in 3 or 4 when that deck is active */
        for (int i = 0; i < 4; i++) {
            comp_bounds(p.lane[i], 156, lane_stock_y[i], 1124, 178);
            lane_inner(p.lane[i], 178);
            comp_visible(p.lane[i], i < 2);
        }
        comp_bounds(p.prev, 0, PREV_STOCK_Y, 1280, 204);
        comp_visible(p.prev, 1);
        g_lanes_four = 0;
        olog("layout: lanes stock\n");
    }
    if (!four && (sidebar || g_lanes_narrow)) {
        /* Keep EP136's active 1/3 and 2/4 pair selection, y positions and
         * waveform timing. Clip only the outer native lane field so it ends
         * before the Beat FX box, just as in the four-deck tab. Repair it on
         * each stock update; stock may restore its original width. */
        stock_lanes_clip(&p, sidebar);
        g_lanes_narrow = sidebar;
    }
    int ours = *(char **) (p.dif + COMP_PARENT) == (char *) view;
    if (four && ours) {
        /* the field sits at y=69: each card lines up with its lane */
        comp_size(p.dif, 156, LANE4_Y0 - 69 + 4 * pitch);
        for (int i = 0; i < 4; i++) {
            comp_bounds(p.card[i], 5, LANE4_Y0 - 69 + pitch * lane_four_row(i), 140, pitch);
        }
        if (g_dif_changed != p.dif) {
            layout_components.repaint(p.dif);
            olog("layout: card field 4-deck\n");
        }
        g_dif_changed = p.dif;
    } else if (g_dif_changed) {
        dif_restore();
    }
    if(four && mixer && ours && (!sidebar || g_fx_sidebar.root)) {
        g_fast_parts=p;
        for(int i=0;i<4;i++)
            g_fast_lane_obj[i]=*(void **)((char *)view+lane_field[i]);
        g_fast_pitch=pitch;
        g_fast_sidebar=sidebar;
        g_fast_mixer=mixer;
        g_fast_ticks=0;
        g_fast_view=view;
    }
    return 0;
}

